/* make.fun client — one stylesheet, no framework, system fonts only (zero font bytes). */

:root {
  --bg: #0b0d10;
  --panel: #12161c;
  --panel-2: #171d25;
  --line: #232b36;
  --ink: #e8edf4;
  --ink-dim: #93a1b5;
  --ink-faint: #5e6b7d;
  --accent: #6ee7a8;
  --accent-ink: #05261a;
  --warn: #ffb65c;
  --dead: #7a8697;
  --radius: 10px;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: #f7f9fb;
    --panel: #ffffff;
    --panel-2: #eef2f7;
    --line: #d9e1ea;
    --ink: #101820;
    --ink-dim: #4e5c6e;
    --ink-faint: #7b8798;
    --accent: #067a4a;
    --accent-ink: #ffffff;
    --warn: #9a5b00;
    --dead: #8b95a3;
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

header.top {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}

.brand {
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.brand span { color: var(--accent); }

nav.top-nav { display: flex; gap: 4px; margin-left: auto; }
nav.top-nav a {
  padding: 5px 10px;
  border-radius: 7px;
  color: var(--ink-dim);
  font-size: 14px;
}
nav.top-nav a:hover { background: var(--panel-2); text-decoration: none; }
nav.top-nav a.on { background: var(--accent); color: var(--accent-ink); font-weight: 600; }

main { max-width: 1080px; margin: 0 auto; padding: 18px 16px 64px; }

h1 { font-size: 22px; line-height: 1.25; margin: 0 0 4px; letter-spacing: -0.015em; }
h2 { font-size: 16px; margin: 24px 0 10px; }
p.sub { color: var(--ink-dim); margin: 0 0 16px; font-size: 14px; }

/* ---- board ---- */

.board { display: grid; gap: 10px; }

.card {
  display: block;
  padding: 13px 14px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: inherit;
}
.card:hover { border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); text-decoration: none; }

.card-top { display: flex; align-items: baseline; gap: 10px; }
.card-title { font-weight: 620; font-size: 15px; flex: 1; min-width: 0; }
.pot { font-family: var(--mono); font-weight: 700; color: var(--accent); white-space: nowrap; }

.card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 7px;
  font-size: 13px;
  color: var(--ink-dim);
}
.card-meta b { color: var(--ink); font-weight: 600; }

.pill {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  border: 1px solid var(--line);
  color: var(--ink-dim);
}
.pill.live { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 40%, var(--line)); }
.pill.soon { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, var(--line)); }
.pill.closed { color: var(--dead); }

/* ---- bounty page ---- */

.bounty-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; }
.bounty-head h1 { flex: 1 1 100%; }
.facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 14px 0 18px; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; }
.fact dt { font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-faint); margin: 0; }
.fact dd { margin: 3px 0 0; font-size: 17px; font-weight: 650; font-family: var(--mono); }
.fact dd.small { font-size: 14px; font-weight: 500; }

.prose { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; }
.prose h3 { font-size: 14px; margin: 16px 0 6px; }
.prose h3:first-child { margin-top: 0; }
.prose p { margin: 0 0 10px; color: var(--ink-dim); }
.prose ul { margin: 0 0 10px; padding-left: 20px; color: var(--ink-dim); }
.prose li { margin: 2px 0; }
.prose code { font-family: var(--mono); font-size: 12.5px; background: var(--panel-2); padding: 1px 5px; border-radius: 4px; }

/* ---- leaderboard ---- */

table.lb { width: 100%; border-collapse: collapse; font-size: 14px; }
table.lb th {
  text-align: left;
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-faint);
  font-weight: 600;
  padding: 6px 8px;
  border-bottom: 1px solid var(--line);
}
table.lb td { padding: 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
table.lb tr:hover td { background: var(--panel); }
table.lb td.num { font-family: var(--mono); white-space: nowrap; }
tr.podium td:first-child { color: var(--accent); font-weight: 700; }

/* ---- profile ---- */

.profile-head { display: flex; gap: 14px; align-items: center; margin-bottom: 18px; }
.avatar {
  width: 64px; height: 64px; border-radius: 50%;
  background: var(--panel-2); border: 1px solid var(--line);
  object-fit: cover; display: grid; place-items: center;
  font-size: 22px; font-weight: 700; color: var(--ink-dim);
}
.kv { display: grid; grid-template-columns: 120px 1fr; gap: 6px 12px; font-size: 14px; }
.kv dt { color: var(--ink-faint); }
.kv dd { margin: 0; color: var(--ink); word-break: break-all; }

/* ---- states ---- */

.loading { color: var(--ink-dim); font-size: 14px; padding: 20px 0; }
.err { color: var(--warn); font-size: 14px; padding: 12px 14px; border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--line)); border-radius: var(--radius); background: var(--panel); }
.empty { color: var(--ink-faint); font-size: 14px; padding: 24px 0; text-align: center; }

.more {
  margin: 16px auto 0; display: block;
  padding: 9px 18px; border-radius: 8px; cursor: pointer;
  background: var(--panel-2); color: var(--ink); border: 1px solid var(--line);
  font: inherit; font-size: 14px;
}
.more:hover { border-color: var(--accent); }

@media (max-width: 640px) {
  main { padding: 14px 12px 56px; }
  h1 { font-size: 19px; }
  .facts { grid-template-columns: repeat(2, 1fr); }
  table.lb th:nth-child(3), table.lb td:nth-child(3) { display: none; }
  nav.top-nav a { padding: 5px 8px; font-size: 13px; }
}
